import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.Dhf_H6O0.js";const p=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md"}'),n={name:"faq.md"};function i(r,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><h3 id="what-is-mcpbehindit" tabindex="-1">What is MCPBehindIT? <a class="header-anchor" href="#what-is-mcpbehindit" aria-label="Permalink to &quot;What is MCPBehindIT?&quot;">​</a></h3><p>MCPBehindIT is a desktop application that runs an MCP (Model Context Protocol) gateway on your Mac. It lets AI tools like Open WebUI connect to various services — Jira, GitLab, Confluence, your local documents, and more — through a single HTTP interface.</p><h3 id="is-mcpbehindit-free" tabindex="-1">Is MCPBehindIT free? <a class="header-anchor" href="#is-mcpbehindit-free" aria-label="Permalink to &quot;Is MCPBehindIT free?&quot;">​</a></h3><p>MCPBehindIT requires a license key from MindBehind IT. Contact MindBehind IT for pricing and availability.</p><h3 id="does-mcpbehindit-send-my-data-to-the-cloud" tabindex="-1">Does MCPBehindIT send my data to the cloud? <a class="header-anchor" href="#does-mcpbehindit-send-my-data-to-the-cloud" aria-label="Permalink to &quot;Does MCPBehindIT send my data to the cloud?&quot;">​</a></h3><p>No. The gateway runs entirely on your Mac inside a Docker container. Your server configurations, documents (for Local RAG), and tool usage stay local. The only network calls are:</p><ul><li>License key validation (to the MindBehind server)</li><li>Connections to remote MCP servers you&#39;ve configured (like Telecontext)</li></ul><p>Local RAG does not upload your documents anywhere.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="can-i-use-mcpbehindit-on-windows" tabindex="-1">Can I use MCPBehindIT on Windows? <a class="header-anchor" href="#can-i-use-mcpbehindit-on-windows" aria-label="Permalink to &quot;Can I use MCPBehindIT on Windows?&quot;">​</a></h3><p>A Windows build is planned but not yet available. Currently, only macOS is supported.</p><h3 id="do-i-need-to-know-docker" tabindex="-1">Do I need to know Docker? <a class="header-anchor" href="#do-i-need-to-know-docker" aria-label="Permalink to &quot;Do I need to know Docker?&quot;">​</a></h3><p>No. MCPBehindIT manages Docker entirely behind the scenes. It can install Docker Desktop for you, start it, pull images, and run containers. You never need to type a Docker command.</p><h3 id="is-docker-desktop-free" tabindex="-1">Is Docker Desktop free? <a class="header-anchor" href="#is-docker-desktop-free" aria-label="Permalink to &quot;Is Docker Desktop free?&quot;">​</a></h3><p>Docker Desktop is free for personal use and small businesses (fewer than 250 employees and less than $10M annual revenue). Larger organizations may need a Docker subscription. See <a href="https://www.docker.com/pricing/" target="_blank" rel="noreferrer">Docker&#39;s pricing page</a> for details.</p><h3 id="the-installer-says-damaged-or-can-t-be-opened" tabindex="-1">The installer says &quot;damaged&quot; or &quot;can&#39;t be opened&quot; <a class="header-anchor" href="#the-installer-says-damaged-or-can-t-be-opened" aria-label="Permalink to &quot;The installer says &quot;damaged&quot; or &quot;can&#39;t be opened&quot;&quot;">​</a></h3><p>Run this command in Terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/MCPBehindIT.app&quot;</span></span></code></pre></div><p>See <a href="./troubleshooting/#macos-issues">Troubleshooting → macOS issues</a> for details.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="how-do-i-update-mcpbehindit" tabindex="-1">How do I update MCPBehindIT? <a class="header-anchor" href="#how-do-i-update-mcpbehindit" aria-label="Permalink to &quot;How do I update MCPBehindIT?&quot;">​</a></h3><p>Run the install command again — it always downloads the latest version:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://halfcross.github.io/mbit-mcpo-proxy-download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>Or download the latest DMG from the <a href="https://github.com/halfcross/mbit-mcpo-proxy-download/releases" target="_blank" rel="noreferrer">Releases page</a>.</p><h3 id="can-i-run-multiple-gateways" tabindex="-1">Can I run multiple gateways? <a class="header-anchor" href="#can-i-run-multiple-gateways" aria-label="Permalink to &quot;Can I run multiple gateways?&quot;">​</a></h3><p>MCPBehindIT runs a single gateway container (<code>mindbehind-mcpo</code>). If you need to run different server configurations, switch between them by enabling/disabling servers and restarting.</p><h3 id="what-happens-if-i-lose-internet-while-using-the-app" tabindex="-1">What happens if I lose internet while using the app? <a class="header-anchor" href="#what-happens-if-i-lose-internet-while-using-the-app" aria-label="Permalink to &quot;What happens if I lose internet while using the app?&quot;">​</a></h3><ul><li><strong>Local servers</strong> (stdio, Local RAG) continue to work normally.</li><li><strong>Remote servers</strong> (Telecontext, SSE endpoints) become unavailable until your connection returns.</li><li><strong>License validation</strong> uses the last known state. If the validation server was reachable recently, the app continues to work. Extended offline periods may trigger re-validation when you reconnect.</li></ul><h3 id="where-is-my-data-stored" tabindex="-1">Where is my data stored? <a class="header-anchor" href="#where-is-my-data-stored" aria-label="Permalink to &quot;Where is my data stored?&quot;">​</a></h3><p>In the app data folder:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Application Support/MindBehind/mcp-orchestrator/</span></span></code></pre></div><p>See <a href="./settings/data-directory.html">Data Directory</a> for a full breakdown.</p><h3 id="can-i-import-servers-from-claude-desktop" tabindex="-1">Can I import servers from Claude Desktop? <a class="header-anchor" href="#can-i-import-servers-from-claude-desktop" aria-label="Permalink to &quot;Can I import servers from Claude Desktop?&quot;">​</a></h3><p>Yes. Copy the <code>mcpServers</code> block from your Claude Desktop config file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Application Support/Claude/claude_desktop_config.json</span></span></code></pre></div><p>Paste it into the <a href="./using-the-app/import-servers.html">Import</a> page in MCPBehindIT and click Analyze.</p><h2 id="telecontext" tabindex="-1">Telecontext <a class="header-anchor" href="#telecontext" aria-label="Permalink to &quot;Telecontext&quot;">​</a></h2><h3 id="what-do-i-need-for-telecontext" tabindex="-1">What do I need for Telecontext? <a class="header-anchor" href="#what-do-i-need-for-telecontext" aria-label="Permalink to &quot;What do I need for Telecontext?&quot;">​</a></h3><ul><li>A Telekom Teleconsole account</li><li>Authorization for each service you want to use set up in Teleconsole: <ul><li><strong>Knowledge</strong> (internal knowledge base), <strong>Tardis</strong> (API platform), <strong>Chatbot Factory</strong> (Telekom chatbots), <strong>PSA</strong> (Privacy &amp; Security Assessment documents), <strong>GitLab</strong>, <strong>Jira</strong>, <strong>Raccoon</strong> (monitoring), <strong>LeanIX</strong> (enterprise architecture), <strong>Confluence</strong>, <strong>Feedback</strong>, <strong>Meta</strong> (utility tools)</li></ul></li><li>MCPBehindIT handles the rest (OAuth sign-in, URL configuration)</li></ul><h3 id="i-signed-into-oauth-but-telecontext-shows-errors" tabindex="-1">I signed into OAuth but Telecontext shows errors <a class="header-anchor" href="#i-signed-into-oauth-but-telecontext-shows-errors" aria-label="Permalink to &quot;I signed into OAuth but Telecontext shows errors&quot;">​</a></h3><ol><li>Check that the services are authorized in your <strong>Teleconsole</strong> account.</li><li>Check <strong>Logs</strong> for specific error messages (401, 405, etc.).</li><li>Try disabling and re-enabling the Telecontext server, then <strong>Apply &amp; Restart</strong>.</li><li>See <a href="./troubleshooting/#oauth-issues">Troubleshooting → OAuth issues</a>.</li></ol><h3 id="can-i-use-only-some-telecontext-tools" tabindex="-1">Can I use only some Telecontext tools? <a class="header-anchor" href="#can-i-use-only-some-telecontext-tools" aria-label="Permalink to &quot;Can I use only some Telecontext tools?&quot;">​</a></h3><p>Yes. The Telecontext configurator lets you select individual categories and tools. Expand a category to see its tools and uncheck the ones you don&#39;t need. Having fewer tools active improves performance and reduces context usage in your AI tool.</p><h2 id="local-rag" tabindex="-1">Local RAG <a class="header-anchor" href="#local-rag" aria-label="Permalink to &quot;Local RAG&quot;">​</a></h2><h3 id="what-file-types-does-local-rag-support" tabindex="-1">What file types does Local RAG support? <a class="header-anchor" href="#what-file-types-does-local-rag-support" aria-label="Permalink to &quot;What file types does Local RAG support?&quot;">​</a></h3><p>PDF, Markdown (.md), DOCX (Microsoft Word), HTML, and source code files. Binary files, images, and videos are not indexed.</p><h3 id="how-much-disk-space-does-local-rag-use" tabindex="-1">How much disk space does Local RAG use? <a class="header-anchor" href="#how-much-disk-space-does-local-rag-use" aria-label="Permalink to &quot;How much disk space does Local RAG use?&quot;">​</a></h3><p>The AI model is about 90 MB (downloaded on first use). The index size depends on your documents — typically a fraction of the original file sizes.</p><h3 id="can-i-index-multiple-folders" tabindex="-1">Can I index multiple folders? <a class="header-anchor" href="#can-i-index-multiple-folders" aria-label="Permalink to &quot;Can I index multiple folders?&quot;">​</a></h3><p>Currently, Local RAG indexes one folder (and its subfolders). If you need to index files from different locations, create a folder with symbolic links or copies of the files you want to include.</p>',52)])])}const g=a(n,[["render",i]]);export{p as __pageData,g as default};
